const icons={home:'house',jobs:'briefcase-business',network:'users-round',school:'graduation-cap',messages:'message-circle',profile:'circle-user-round',settings:'settings',search:'search',menu:'menu',close:'panel-left-close',open:'panel-left-open',bell:'bell',arrow:'arrow-up-right',calendar:'calendar-days',bookmark:'bookmark',check:'check',globe:'globe-2'};
const paths={house:'M3 10.5 12 3l9 7.5V21h-6v-7H9v7H3z','briefcase-business':'M3 7h18v14H3z M8 7V4h8v3 M3 12h18','users-round':'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M16 3.13a4 4 0 0 1 0 7.75','graduation-cap':'m2 10 10-5 10 5-10 5z M6 12v5c4 3 8 3 12 0v-5 M22 10v6','message-circle':'M21 11.5a8.5 8.5 0 0 1-8.5 8.5 9 9 0 0 1-4-.9L3 21l1.9-5.5a9 9 0 0 1-.9-4A8.5 8.5 0 0 1 12.5 3a8.5 8.5 0 0 1 8.5 8.5z','circle-user-round':'M20 21a8 8 0 1 0-16 0 M12 13a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20',settings:'M12 15.5a3.5 3.5 0 1 0 0-7 3.5 3.5 0 0 0 0 7 M19.4 15a1.7 1.7 0 0 0 .34 1.88l.06.06-2 2-.06-.06a1.7 1.7 0 0 0-1.88-.34l-.09.04V21h-3v-.09a1.7 1.7 0 0 0-1.12-1.6 M4.6 9a1.7 1.7 0 0 0-.34-1.88L4.2 7.06l2-2 .06.06a1.7 1.7 0 0 0 1.88.34L8.23 5V3h3v.09 M20 9l.8-1.9-2-2-.1.1','search':'m21 21-4.4-4.4 M19 11a8 8 0 1 1-16 0 8 8 0 0 1 16 0',menu:'M4 6h16 M4 12h16 M4 18h16','panel-left-close':'M3 4h18v16H3z M9 4v16 m7-11-3 3 3 3','panel-left-open':'M3 4h18v16H3z M9 4v16 m4-11 3 3-3 3',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4','arrow-up-right':'M7 17 17 7 M7 7h10v10','calendar-days':'M3 5h18v16H3z M7 3v4 M17 3v4 M3 10h18 M7 14h2 M12 14h2','bookmark':'M5 3h14v18l-7-5-7 5z',check:'M4 12l5 5L20 6','globe-2':'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20 M2 12h20 M12 2c-6 6-6 14 0 20 M12 2c6 6 6 14 0 20'};
function ico(name,size=19){let s=paths[icons[name]||name]||paths.house;return '<svg width="'+size+'" height="'+size+'" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+s+'"/></svg>'}
const opportunities=[{name:'Stage Développeur Full Stack',company:'Wave Sénégal',initial:'W',location:'Dakar, Sénégal',type:'Stage',sector:'Technologie',date:'Il y a 2 h'},{name:'Assistant(e) Marketing Digital',company:'Orange Sénégal',initial:'O',location:'Dakar · Hybride',type:'Stage',sector:'Marketing',date:'Il y a 5 h'},{name:'Junior Data Analyst',company:'Sonatel',initial:'S',location:'Dakar, Sénégal',type:'Emploi',sector:'Data',date:'Hier'},{name:'UX/UI Designer Junior',company:'Jokkolabs',initial:'J',location:'Dakar · À distance',type:'Emploi',sector:'Design',date:'Il y a 2 j'},{name:'Stage Audit & Contrôle',company:'Cabinet Horizon',initial:'H',location:'Dakar, Sénégal',type:'Stage',sector:'Finance',date:'Il y a 3 j'}];
const people=[{name:'Awa Diop',role:'Développeuse frontend · Alumni',initial:'AD'},{name:'Moussa Fall',role:'Data Analyst · Alumni',initial:'MF'},{name:'Fatou Ndiaye',role:'Responsable recrutement',initial:'FN'},{name:'Ibrahima Ba',role:'Étudiant en informatique',initial:'IB'}];
const pages=[['home','Accueil'],['jobs','Offres'],['network','Réseau'],['school','Établissements'],['messages','Messages'],['profile','Mon profil']];
let view='home',collapsed=false,mobile=false,filter='Toutes',query='',saved=new Set(),role='Étudiant';
const app=document.getElementById('app');
function notify(message){document.querySelector('.toast')?.remove();let t=document.createElement('div');t.className='toast';t.textContent=message;document.body.append(t);setTimeout(()=>t.remove(),3000)}
function sidebar(){return '<aside class="sidebar" id="primary-navigation" aria-label="Navigation principale"><div class="brand"><img class="full-logo" src="/assets/logo.png" alt="G-Connect"><img class="compact-logo" src="/assets/logo_icon.png" alt="G"><button class="icon-btn collapse-trigger" id="collapse" aria-controls="primary-navigation" aria-expanded="'+(!collapsed)+'" title="Réduire ou déployer la navigation">'+ico('close')+'</button></div><div class="searchbox"><button id="search-trigger" aria-label="Rechercher">'+ico('search')+'</button><input id="side-search" placeholder="Rechercher..." value="'+escapeHTML(query)+'" aria-label="Rechercher sur G-Connect"></div><div class="nav-label">Menu principal</div><nav class="nav">'+pages.map(([key,label])=>'<button class="nav-btn '+(view===key?'active':'')+'" data-page="'+key+'" title="'+label+'">'+ico(key)+'<span>'+label+'</span></button>').join('')+'</nav><div class="side-bottom"><div class="nav-label">Compte</div><button class="nav-btn '+(view==='settings'?'active':'')+'" data-page="settings" title="Paramètres">'+ico('settings')+'<span>Paramètres</span></button><div class="profile-small"><div class="avatar">TT</div><div><strong>Mon espace G-Connect</strong><small>Compte de démonstration</small></div></div></div></aside>'}
function topbar(){return '<header class="topbar"><div style="display:flex;align-items:center;gap:10px"><button class="icon-btn mobile-toggle" id="mobile-menu" aria-controls="primary-navigation" aria-expanded="'+mobile+'" aria-label="Ouvrir le menu">'+ico('menu',22)+'</button><img class="mobile-brand" src="/assets/logo.png" alt="G-Connect"><div class="breadcrumb">G-Connect &nbsp; / &nbsp; <b>'+([ ...pages,['settings','Paramètres']].find(p=>p[0]===view)||pages[0])[1]+'</b></div></div><div class="top-actions"><button class="round" id="notifications" title="Notifications">'+ico('bell')+'</button><div class="member-pill"><div class="avatar">TT</div><span>Mon espace</span></div></div></header>'}
function stats(){return '<div class="stats"><div class="stat"><div class="stat-icon">'+ico('jobs',24)+'</div><div><strong>24</strong><small>Opportunités à découvrir</small></div></div><div class="stat"><div class="stat-icon">'+ico('network',24)+'</div><div><strong>128</strong><small>Membres dans votre réseau</small></div></div><div class="stat"><div class="stat-icon">'+ico('school',24)+'</div><div><strong>12</strong><small>Établissements partenaires</small></div></div></div>'}
function opportunity(o,i){return '<article class="op-card"><div class="company" style="background:'+(['#1c2c67','#ff9b3c','#315bd7','#254d51','#8264cc'][i%5])+'">'+o.initial+'</div><div class="op-main"><h3>'+o.name+'</h3><p>'+o.company+' · '+o.location+' · '+o.date+'</p><div class="tag-row"><span class="tag">'+o.type+'</span><span class="tag green">'+o.sector+'</span></div></div><button class="apply" data-save="'+i+'">'+(saved.has(i)?'Enregistré ✓':'Sauvegarder')+'</button></article>'}
function home(){return '<div class="page"><section class="hero"><div class="hero-copy"><span class="eyebrow">Bienvenue dans votre communauté</span><h1>Votre réseau aujourd’hui.<br>Vos opportunités demain.</h1><p>Rencontrez les bonnes personnes, explorez les offres qui vous correspondent et avancez avec votre communauté académique.</p><div class="actions"><button class="btn white" data-page="jobs">Explorer les offres '+ico('arrow',16)+'</button><button class="btn outline" data-page="network">Découvrir le réseau</button></div></div><img class="hero-photo" src="/assets/hero-gconnect.jpg" alt="Un jeune professionnel noir avec son ordinateur, en extérieur" width="800" height="900" fetchpriority="high"></section>'+'<p class="demo-note">Espace de démonstration · Offres, profils et événements présentés à titre d’exemple.</p><div class="dash-grid"><div><div class="section-head"><div><h2>Opportunités à la une</h2><p>Une sélection pour commencer votre parcours</p></div><button class="text-link" data-page="jobs">Voir toutes les offres →</button></div><div class="op-list">'+opportunities.slice(0,3).map(opportunity).join('')+'</div></div><div><div class="section-head"><div><h2>À ne pas manquer</h2><p>Les prochains rendez-vous</p></div></div><div class="panel"><h3>Événements du réseau</h3>'+[['24','OCT','Rencontre Alumni','Échange autour des métiers du numérique'],['07','NOV','Forum stages & emplois','Entreprises et étudiants réunis'],['15','NOV','Atelier CV & LinkedIn','Valoriser son parcours']].map(x=>'<div class="event"><div class="date-tile"><strong>'+x[0]+'</strong><small>'+x[1]+'</small></div><div><b>'+x[2]+'</b><p>'+x[3]+'</p></div></div>').join('')+'<button class="text-link" data-page="school">Explorer les établissements →</button></div></div></div><div class="wide-banner"><div><h3>Votre parcours mérite d’être vu.</h3><p>Complétez votre profil pour vous présenter à votre communauté.</p></div><button class="btn primary" data-page="profile">Compléter mon profil '+ico('arrow',15)+'</button></div></div>'}
function jobs(){let items=opportunities.filter(o=>(filter==='Toutes'||o.type===filter)&&[o.name,o.company,o.sector].join(' ').toLowerCase().includes(query.toLowerCase()));return '<div class="page"><div class="intro"><span class="eyebrow" >Carrière & opportunités</span><h1>Trouvez votre prochaine opportunité.</h1><p>Explorez les offres proposées par les entreprises de notre réseau.</p></div><div class="search-large">'+ico('search')+'<input id="big-search" aria-label="Rechercher une offre" placeholder="Rechercher un poste, une entreprise, un domaine..." value="'+escapeHTML(query)+'"></div><div class="filters">'+['Toutes','Stage','Emploi'].map(f=>'<button class="chip '+(filter===f?'active':'')+'" data-filter="'+f+'">'+f+'</button>').join('')+'</div><div class="op-list">'+(items.length?items.map(o=>opportunity(o,opportunities.indexOf(o))).join(''):'<div class="empty">Aucun résultat. Essayez un autre mot-clé.</div>')+'</div></div>'}
function network(){return '<div class="page"><div class="intro"><span class="eyebrow" >Une communauté, des connexions</span><h1>Grandissez ensemble.</h1><p>Découvrez des profils et développez votre réseau professionnel.</p></div><div class="section-head"><h2>Membres à découvrir</h2></div><div class="cards-grid">'+people.map(p=>'<article class="people-card"><div class="avatar">'+p.initial+'</div><h3>'+p.name+'</h3><p>'+p.role+'</p><button class="btn primary invite">Se connecter</button></article>').join('')+'</div></div>'}
function schools(){return '<div class="page"><div class="intro"><span class="eyebrow" >Écoles et universités</span><h1>Votre communauté académique.</h1><p>Retrouvez votre établissement et développez vos liens avec les promotions.</p></div><div class="cards-grid" style="margin-top:24px">'+[['ISI','Institut Supérieur d’Informatique'],['UCAD','Université Cheikh Anta Diop'],['ESP','École Supérieure Polytechnique']].map(([a,b])=>'<article class="people-card"><div class="avatar">'+a[0]+'</div><h3>'+b+'</h3><p>Dakar, Sénégal</p><button class="btn primary join">Découvrir</button></article>').join('')+'</div></div>'}
function messages(){return '<div class="page"><div class="intro"><span class="eyebrow" >Conversations</span><h1>Messages</h1><p>Échangez avec votre réseau et vos contacts.</p></div><div class="panel" style="margin-top:24px"><div class="empty">'+ico('messages',30)+'<h3>Aucune conversation pour le moment</h3><p>La messagerie sera activée après l’intégration de l’authentification et du backend.</p><button class="btn primary" data-page="network">Explorer le réseau</button></div></div></div>'}
function profile(){return '<div class="page"><div class="intro"><span class="eyebrow" >Mon identité professionnelle</span><h1>Votre profil G-Connect</h1><p>Présentez votre parcours et vos ambitions à votre communauté.</p></div><div class="auth-panel"><div style="display:flex;align-items:center;gap:15px"><div class="avatar" style="width:68px;height:68px;font-size:22px">TT</div><div><h2 style="margin:0">Bienvenue sur G-Connect</h2><p style="font-size:12px;color:#8896b0">Configurez votre futur profil</p></div></div><div class="form-field"><label for="profile-name">Nom complet</label><input id="profile-name" placeholder="Votre nom et prénom"></div><div class="form-field"><label for="role">Type de profil</label><select id="role">'+['Étudiant','Alumni','Entreprise','Établissement'].map(r=>'<option '+(role===r?'selected':'')+'>'+r+'</option>').join('')+'</select></div><div class="form-field"><label for="profile-bio">Votre présentation</label><input id="profile-bio" placeholder="Votre filière, poste ou domaine"></div><button class="btn primary preview-only">Enregistrer mon profil</button><p class="fine">Aperçu frontend : l’enregistrement réel sera disponible après connexion à l’API.</p></div></div>'}
function settings(){return '<div class="page"><div class="intro"><h1>Préférences</h1><p>Personnalisez votre expérience.</p></div><div class="panel" style="margin-top:24px"><h3>Navigation</h3><p style="color:#8391aa;font-size:13px">Vous pouvez réduire ou déployer la barre latérale avec le bouton situé en haut de celle-ci.</p><button class="btn primary" id="toggle-settings">Basculer la sidebar</button></div></div>'}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function render(){const content={home,jobs,network,school:schools,messages,profile,settings}[view]();app.innerHTML='<a class="skip-link" href="#main-content">Aller au contenu</a><div class="shell '+(collapsed?'collapsed ':'')+(mobile?'mobile-open':'')+'"><div class="mobile-backdrop" id="backdrop"></div>'+sidebar()+'<main class="content" id="main-content" tabindex="-1">'+topbar()+content+'</main></div>';document.title=([ ...pages,['settings','Paramètres']].find(p=>p[0]===view)||pages[0])[1]+' · G-Connect';bind()}
function navigate(v){view=v;query='';mobile=false;render();window.scrollTo({top:0,behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}
function updateNavigation(){const shell=document.querySelector('.shell');shell.classList.toggle('collapsed',collapsed);shell.classList.toggle('mobile-open',mobile);document.getElementById('collapse').setAttribute('aria-expanded',String(!collapsed));document.getElementById('mobile-menu').setAttribute('aria-expanded',String(mobile))}
function bind(){document.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>navigate(el.dataset.page));document.getElementById('collapse').onclick=()=>{if(innerWidth<=720){mobile=false}else{collapsed=!collapsed}updateNavigation()};document.getElementById('mobile-menu').onclick=()=>{mobile=true;updateNavigation()};document.getElementById('backdrop').onclick=()=>{mobile=false;updateNavigation()};document.getElementById('search-trigger').onclick=()=>{if(collapsed){collapsed=false;updateNavigation();document.getElementById('side-search').focus()}else document.getElementById('side-search').focus()};const side=document.getElementById('side-search');side.onkeydown=e=>{if(e.key==='Enter'){query=side.value;view='jobs';mobile=false;render();document.getElementById('big-search')?.focus()}};document.querySelectorAll('[data-save]').forEach(el=>el.onclick=()=>{let i=+el.dataset.save;saved.has(i)?saved.delete(i):saved.add(i);notify(saved.has(i)?'Offre ajoutée aux favoris':'Offre retirée des favoris');render()});document.querySelectorAll('[data-filter]').forEach(el=>el.onclick=()=>{filter=el.dataset.filter;render()});const search=document.getElementById('big-search');if(search){search.oninput=()=>{query=search.value;let pos=search.selectionStart;render();let replacement=document.getElementById('big-search');replacement.focus();replacement.setSelectionRange(pos,pos)}}document.querySelectorAll('.invite,.join,.preview-only').forEach(el=>el.onclick=()=>notify('Cette action sera disponible après la connexion au backend.'));document.getElementById('notifications').onclick=()=>notify('Aucune nouvelle notification');let r=document.getElementById('role');if(r)r.onchange=()=>role=r.value;let toggle=document.getElementById('toggle-settings');if(toggle)toggle.onclick=()=>{if(innerWidth<=720){mobile=!mobile}else{collapsed=!collapsed}updateNavigation()}}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&mobile){mobile=false;updateNavigation();document.getElementById('mobile-menu').focus()}});
render();
